'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dlaln2 = require( './../lib' );

// Specify matrix meta data:
var shape = [ 2, 2 ];
var order = 'row-major';
var strides = shape2strides( shape, order );

// Create a 2x2 matrix `A` stored in linear memory:
var A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
console.log( ndarray2array( A, shape, strides, 0, order ) );

// Create a 2x2 right-hand side `B` whose columns are the real and imaginary parts of a complex right-hand side:
var B = new Float64Array( [ 1.0, 3.0, 2.0, 4.0 ] );
console.log( ndarray2array( B, shape, strides, 0, order ) );

// Allocate an output matrix `X` and output arrays for the scaling factor, the infinity-norm of `X`, and the status code:
var X = new Float64Array( 4 );
var scale = new Float64Array( 1 );
var xnorm = new Float64Array( 1 );
var info = new Int32Array( 1 );

// Solve (A - (0.5 + 0.5i) I) X = s B:
dlaln2( order, 'no-transpose', 2, 2, 1.0e-3, 1.0, A, strides[ 0 ], 1.0, 1.0, B, strides[ 0 ], 0.5, 0.5, X, strides[ 0 ], scale, xnorm, info );
console.log( ndarray2array( X, shape, strides, 0, order ) );
console.log( scale );
console.log( xnorm );
console.log( info );
